class FakeChatService extends ChangeNotifier implements FaChatService {
  final TrajectoryServiceFeed feed = TrajectoryServiceFeed();

  @override
  Stream<TrajectorySnapshot> get trajectory => feed.stream;

  /// Settable hidden-range resolver (issue #385 F4) — tests assign this
  /// to exercise the drill-in tab; null hides it.
  @override
  Future<List<TrajectoryHiddenRecordPreview>> Function(
    TrajectoryCompactedRecord record,
  )?
  resolveHiddenRecords;
  @override
  List<FaChatMessage> get messages => const [];
  @override
  ExecutionEnv? get sandboxEnv => null;
  @override
  bool get isStreaming => false;
  @override
  String? get error => null;
  @override
  List<String> get pendingSteerTexts => const [];
  @override
  Future<void> sendText(String text) async {}
  @override
  Future<void> sendAttachments({
    required List<FaStagedAttachment> attachments,
    String text = '',
  }) async {}

  /// Files handed to [stageAttachment], in order — drop/paste tests assert
  /// against this log.
  final List<({String name, Uint8List bytes})> stagedCalls = [];
  @override
  Future<String> stageAttachment({
    required String name,
    required Uint8List bytes,
  }) async {
    stagedCalls.add((name: name, bytes: bytes));
    return name;
  }
  @override
  Future<void> discardStagedAttachment(String path) async {}
  @override
  void abort() {}
  @override
  String transcriptMarkdown() => '';
  @override
  int? get historyAboveCount => 0;
  @override
  String? historyLoadError;
  int loadOlderHistoryCalls = 0;
  @override
