    loadOlderHistoryCalls++;
  }

  @override
  bool get historyLoading => false;
  @override
  int? get historyTotalCount => null;

  /// Set by tests to drive the "Load newer" banner.
  bool hasNewer = false;
  @override
  bool get historyHasNewer => hasNewer;
  @override
  int? get historyBelowCount => 0;

